// Import Vue and createApp from 'vue'
import { createApp } from 'vue'

// Import createRouter and createWebHistory from 'vue-router'
import { createRouter, createWebHistory } from 'vue-router'

// Create the Home component
const Home = { template: '<h2>Home Page</h2>' }

// Define About component using dynamic import syntax
const About = () => import('./About.vue')

// Define routes array with lazy loading
const routes = [
  { path: '/', component: Home },
  { path: '/about', component: About }
]

// Create router instance
const router = createRouter({
  history: createWebHistory(),
  routes
})

// Create App component
const App = { template: '<router-view />' }

// Create and mount the Vue application
const app = createApp(App)
app.use(router)
app.mount('#app')
